export function presentationAsset(id,kind='artwork'){return PRESENTATION_ASSET_PATHS[String(id||'')]?.[kind]||PRESENTATION_ASSET_FALLBACK;}
export function hasBespokeAsset(id,kind='artwork'){const key=String(id||'');return kind==='front'?BESPOKE_FRONT_IDS.has(key):kind==='back'?BESPOKE_BACK_IDS.has(key):BESPOKE_ARTWORK_IDS.has(key);}
